SELECT JSON_OBJECT('target',CONCAT('mock_exam_bank:',p.id),'id',p.id,'table','mock_exam_bank','status',CASE WHEN q.id IS NULL THEN 'MISSING_TARGET' WHEN r.revision_key IS NOT NULL AND NOT (r.question_id=p.id AND BINARY CAST(r.before_content AS CHAR)=BINARY CAST(p.before_content AS CHAR) AND BINARY CAST(r.after_content AS CHAR)=BINARY CAST(p.after_content AS CHAR) AND BINARY CAST(r.evidence_urls AS CHAR)=BINARY CAST(p.evidence_urls AS CHAR)) THEN 'ARCHIVE_CONFLICT' WHEN BINARY CAST(JSON_OBJECT('id',q.id,'sourceType',q.source_type,'paperType',q.paper_type,'kind',q.kind,'subject',q.subject,'difficulty',q.difficulty,'stem',q.stem,'options',q.options_json,'answer',q.reference_answer,'explanation',q.explanation,'sourceLabel',q.source_label,'sourceUrl',q.source_url,'readingUrl',q.reading_url) AS CHAR)=BINARY CAST(p.after_content AS CHAR) AND r.applied_at IS NOT NULL THEN 'APPLIED_OR_ALREADY_APPLIED' ELSE 'BASELINE_CHANGED' END) FROM teaching_mock_proposal p LEFT JOIN mock_exam_bank q ON q.id=p.id LEFT JOIN mock_exam_content_revision r ON r.revision_key=p.revision_key ORDER BY p.id;
